using HRIS.Api.Data; using HRIS.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Repositories;
public class LaptopRepository : ILaptopRepository { private readonly AppDbContext _db; public LaptopRepository(AppDbContext db)=>_db=db; private IQueryable<LaptopRequest> Base()=>_db.LaptopRequests.Include(x=>x.Employee).Include(x=>x.StatusLogs).ThenInclude(l=>l.ChangedByUser); public Task<List<LaptopRequest>> GetAllAsync(int? employeeId=null)=>Base().Where(x=>employeeId==null||x.EmployeeId==employeeId).OrderByDescending(x=>x.CreatedAt).ToListAsync(); public Task<LaptopRequest?> GetByIdAsync(int id)=>Base().FirstOrDefaultAsync(x=>x.Id==id); public async Task<LaptopRequest> AddAsync(LaptopRequest x){_db.LaptopRequests.Add(x);await _db.SaveChangesAsync();return x;} public async Task UpdateAsync(LaptopRequest x)=>await _db.SaveChangesAsync(); public async Task<LaptopStatusLog> AddLogAsync(LaptopStatusLog x){_db.LaptopStatusLogs.Add(x);await _db.SaveChangesAsync();return x;} }
